/**
 * PDF renderer css variable names
 */
export class PdfCssVariableNames {
    /** Contents container width */
    static readonly ContentsContainerWidth = "--pdf-contents-container-width";
    /** Contents container offset left */
    static readonly ContentsContainerOffsetLeft = "--pdf-contents-container-offsetleft";

    /** Scroll element overflow */
    static readonly ScrollElementOverflow = "--pdf-scroll-element-overflow";
    /** Scroll element vertical scrollbar width */
    static readonly ScrollElementVerticalScrollBarWidth = "--pdf-scroll-element-vertial-scrollbar-width";
    /** Scroll element horizontal scrollbar height */
    static readonly ScrollElementHorizontalScrollBarHeight = "--pdf-scroll-element-horizontal-scrollbar-height";
    /** Default content container width */
    static readonly ContentContainerWidth = "--pdf-content-container-width";
    /**Each content wrapper container corner radius */
    static readonly ContentWrapperBorderRadius = "--pdf-content-wrapper-border-radius";
}
